import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"SOLID 与依赖规则","description":"","frontmatter":{},"headers":[],"relativePath":"evolution/solid.md","filePath":"evolution/solid.md","lastUpdated":1791594310000}`),a={name:`evolution/solid.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="solid-与依赖规则" tabindex="-1">SOLID 与依赖规则 <a class="header-anchor" href="#solid-与依赖规则" aria-label="Permalink to “SOLID 与依赖规则”">​</a></h1><p>SOLID 是五条类与组件设计原则的首字母缩写，出处是 Martin 2002 年那本书 [S4]，2017 年的《架构整洁之道》把它与依赖规则、组件原则合在一起讲 [S3]。它的作用不是让代码&quot;更优雅&quot;，而是给出一个可检查的判断：改一个需求时，需要动的文件有几个。</p><h2 id="五条原则与站内对应" tabindex="-1">五条原则与站内对应 <a class="header-anchor" href="#五条原则与站内对应" aria-label="Permalink to “五条原则与站内对应”">​</a></h2><h3 id="单一职责-srp" tabindex="-1">单一职责（SRP） <a class="header-anchor" href="#单一职责-srp" aria-label="Permalink to “单一职责（SRP）”">​</a></h3><p>一个类只有一个引起它变化的理由。判断方法是把&quot;将来可能变化的原因&quot;列出来，超过一条就该拆。</p><p>站内对应：<a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>是 SRP 反面的极端形态，其&quot;按不变式分组搬字段&quot;的拆法就是按职责分。</p><h3 id="开闭原则-ocp" tabindex="-1">开闭原则（OCP） <a class="header-anchor" href="#开闭原则-ocp" aria-label="Permalink to “开闭原则（OCP）”">​</a></h3><p>对扩展开放、对修改关闭。新增一种情况时应当新增文件，而不是在已有 <code>switch</code> 里加分支。</p><p>站内对应：<a href="/hello-design-patterns/behavioral/strategy">策略</a>把&quot;算法可换&quot;做成加一个类；<a href="/hello-design-patterns/creational/factory-method">工厂方法</a>与<a href="/hello-design-patterns/creational/abstract-factory">抽象工厂</a>把&quot;实例化哪个类&quot;挪出调用方；<a href="/hello-design-patterns/structural/decorator">装饰</a>在不改原类的前提下叠职责。Head First 在观察者一章讲的就是这条 [S2]。</p><h3 id="里氏替换-lsp" tabindex="-1">里氏替换（LSP） <a class="header-anchor" href="#里氏替换-lsp" aria-label="Permalink to “里氏替换（LSP）”">​</a></h3><p>子类替换父类后，调用方不该察觉。违反的典型是子类抛出父类不抛的异常、或者要求调用方先调某个子类特有的方法。</p><p>站内对应：组合替代继承可直接绕开这条约束，见<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>；留下的继承则要求子类实现完整语义，<a href="/hello-design-patterns/behavioral/template-method">模板方法</a>的骨架方法就是靠这个约定工作的。</p><h3 id="接口隔离-isp" tabindex="-1">接口隔离（ISP） <a class="header-anchor" href="#接口隔离-isp" aria-label="Permalink to “接口隔离（ISP）”">​</a></h3><p>不要强迫实现方实现它用不到的方法。接口按使用方的需要拆，而不是按提供方的能力列。</p><p>站内对应：Go 的&quot;接口由使用方定义&quot;是 ISP 的语言级实现 [S21]；<a href="/hello-design-patterns/structural/adapter">适配器</a>常做的正是把胖接口切成几个小接口再分别提供。</p><h3 id="依赖倒置-dip" tabindex="-1">依赖倒置（DIP） <a class="header-anchor" href="#依赖倒置-dip" aria-label="Permalink to “依赖倒置（DIP）”">​</a></h3><p>高层模块不依赖低层模块，两者都依赖抽象；抽象不依赖细节，细节依赖抽象。</p><p>站内对应：<a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>是 DIP 的装配手段，<a href="/hello-design-patterns/creational/service-locator">服务定位器</a>是它的另一种做法但把依赖藏进了实现（Fowler 把后者列为反模式 [S26]）。两篇对照读。</p><h2 id="依赖规则" tabindex="-1">依赖规则 <a class="header-anchor" href="#依赖规则" aria-label="Permalink to “依赖规则”">​</a></h2><p>《架构整洁之道》[S3] 在五条之上加了一条方向约束：源代码依赖只能指向内层，内层不知道外层的存在。</p><div class="language- line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8;" tabindex="0" dir="ltr"><code><span class="line"><span>实体（企业规则） ← 用例（应用规则） ← 接口适配器 ← 框架与驱动</span></span>
<span class="line"><span>        越往内越稳定，越往外越易变</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>含义是具体的：领域层不能 import 框架的注解，不能出现数据库连接、HTTP 请求这些词。站内<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>的改造之所以把规则搬回实体，正是为了让内层不再依赖外层的仓储与服务。</p><h2 id="组件级三原则-延伸" tabindex="-1">组件级三原则（延伸） <a class="header-anchor" href="#组件级三原则-延伸" aria-label="Permalink to “组件级三原则（延伸）”">​</a></h2><p>《架构整洁之道》还给了包与组件级别的三条：复用与使用等价（不能让同一个组件既被使用又依赖使用者）、稳定依赖（不稳定的东西依赖稳定的）、无环依赖（包之间不能成环，用依赖倒置破环）。站内暂无组件设计专篇；同书的分层架构、管道-过滤器按<a href="/hello-design-patterns/research/coverage">差异表</a>已定的口径（约束全系统拓扑的架构风格不收）维持不收录，需要时以 [S3] 原书为准。</p><h2 id="用它做一次体检" tabindex="-1">用它做一次体检 <a class="header-anchor" href="#用它做一次体检" aria-label="Permalink to “用它做一次体检”">​</a></h2><p>按这五步过一个模块，产出是几份可执行的清单，不是一份评分：</p><ol><li>列出模块里每个类的&quot;变化理由&quot;，重复的合并，超过一条的标 SRP 问题。</li><li>找所有 <code>switch</code>/<code>if-else</code> 按类型分支的地方，逐条问&quot;新增一种要改几个文件&quot;，两个以上的标 OCP 问题。</li><li>找子类，看有没有父类没要求、子类却抛出或抛回的异常，标 LSP 问题。</li><li>找实现方从没用过的方法，标 ISP 问题。</li><li>找领域代码里的框架注解、SQL 字符串、URL 字面量，标 DIP 问题。</li></ol><p>标完按&quot;改一个需求要动几个文件&quot;排序，先动最疼的那个。这比一次改完所有问题有效：一次改完的重构通常没有回归保护，见<a href="/hello-design-patterns/anti-patterns/spaghetti-code">意面代码</a>第 1 步。</p><h2 id="五条原则不是目标" tabindex="-1">五条原则不是目标 <a class="header-anchor" href="#五条原则不是目标" aria-label="Permalink to “五条原则不是目标”">​</a></h2><p>原则是代价的记账方式。每个 <code>interface</code> 都要付出多一层间接的阅读成本，每拆一个类都要付出多一次跳转的阅读成本。什么时候值得：预计会变的地方才值得按原则切，一次性脚本按原则切只会更难读。Martin 自己在 [S3] 里的口径也是按稳定度分层，不是要求所有代码都做到五条。</p><h2 id="相关篇目" tabindex="-1">相关篇目 <a class="header-anchor" href="#相关篇目" aria-label="Permalink to “相关篇目”">​</a></h2><ul><li><a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>：LSP 的绕开方式，也是五条原则的共同底座。</li><li><a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>、<a href="/hello-design-patterns/creational/service-locator">服务定位器</a>：DIP 的两种落法。</li><li><a href="/hello-design-patterns/behavioral/strategy">策略</a>、<a href="/hello-design-patterns/creational/factory-method">工厂方法</a>、<a href="/hello-design-patterns/structural/decorator">装饰</a>：OCP 的三个常用工具。</li><li><a href="/hello-design-patterns/anti-patterns/overview">反模式导读</a>：五条的反面案例在这里。</li></ul><h2 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to “来源”">​</a></h2><ul><li>[S3] Robert C. Martin，《Clean Architecture》，2017。依赖规则与组件原则。</li><li>[S4] Robert C. Martin，《Agile Software Development: Principles, Patterns, and Practices》，2002。SOLID 出处。</li><li>[S2] 《Head First Design Patterns》第 2 版，2020，开闭原则的入门讲法。</li><li>[S26] martinfowler.com bliki，服务定位器作为反模式的论述。</li></ul>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};